    kapitel: "67",
    title: "6.3.1 Aufstockungen aufgrund des Einbringungsgewinns",
    thema: "Wertaufstockung bei der Übernehmerin aufgrund des Einbringungsgewinns nach § 23 Abs. 2 UmwStG",
    rechtsstand: STAND,
